export const DEFAULT_EMPLOYEE_PROFILE = {
  skills: [],
  startDate: null,
  photo: null,
  socialLink: '',
  phone: '',
};

export function getEmployeeProfile(employee) {
  if (!employee) return { ...DEFAULT_EMPLOYEE_PROFILE };
  return {
    skills: Array.isArray(employee.skills) ? employee.skills : [],
    startDate: employee.startDate ?? null,
    photo: employee.photo ?? null,
    socialLink: employee.socialLink ?? '',
    phone: employee.phone ?? '',
  };
}

export function buildEmployeeMetaMap(employees) {
  return Object.fromEntries(
    employees.map((e) => [e.id, getEmployeeProfile(e)])
  );
}
