import { useEffect, useRef } from 'react';
import { getEmployeeProfile } from '../utils/employeeUtils';

const LOCAL_KEY = 'cpito_local_skills_v1';
const MIGRATION_KEY = 'cpito_cloud_migrated_v2';

function loadLocalState() {
  try {
    const raw = localStorage.getItem(LOCAL_KEY);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export function useCloudMigration(employees, updateEmployeeProfile, mergeSkillsCatalog) {
  const runningRef = useRef(false);

  useEffect(() => {
    if (runningRef.current || !employees.length) return;
    if (localStorage.getItem(MIGRATION_KEY)) return;

    const local = loadLocalState();
    if (!local) {
      localStorage.setItem(MIGRATION_KEY, '1');
      return;
    }

    runningRef.current = true;

    (async () => {
      try {
        const catalog = Array.isArray(local.catalog) ? local.catalog : [];
        if (catalog.length) await mergeSkillsCatalog(catalog);

        const employeeMeta = local.employeeMeta ?? {};
        for (const employee of employees) {
          const localMeta = employeeMeta[employee.id];
          if (!localMeta) continue;

          const current = getEmployeeProfile(employee);
          const patch = {};

          if (!current.startDate && localMeta.startDate) {
            patch.startDate = localMeta.startDate;
          }
          if (!current.photo && localMeta.photo) patch.photo = localMeta.photo;
          if (!current.phone && localMeta.phone) patch.phone = localMeta.phone;
          if (!current.socialLink && localMeta.socialLink) {
            patch.socialLink = localMeta.socialLink;
          }
          if ((!current.skills || current.skills.length === 0) && localMeta.skills?.length) {
            patch.skills = localMeta.skills;
          }

          if (Object.keys(patch).length > 0) {
            await updateEmployeeProfile(employee.id, patch);
          }
        }

        localStorage.removeItem(LOCAL_KEY);
        localStorage.setItem(MIGRATION_KEY, '1');
      } catch (error) {
        console.error('Ошибка миграции в облако:', error);
      } finally {
        runningRef.current = false;
      }
    })();
  }, [employees, updateEmployeeProfile, mergeSkillsCatalog]);
}
