import React, { useState, useEffect, useMemo } from 'react';
import { EmployeeCard } from './EmployeeCard';
import { employeeInExperienceBucket, getEmployeeExperienceMonths, getTeamColor } from '../../utils/teamUtils';
import './EmployeesPanel.css';

function sortByName(a, b) {
  return a.name.localeCompare(b.name, 'ru');
}

export function EmployeesPanel({
  employees,
  assignments,
  projects,
  teams,
  onRemoveAssignment,
  onAddEmployee,
  onAddTeam,
  onSetEmployeeTeam,
  onRemoveEmployee,
  skillsCatalog,
  onAddSkill,
  onRemoveSkill,
  getEmployeeMeta,
  onToggleSkill,
  onSetStartDate,
  onSetPhoto,
  onSetSocialLink,
  onSetPhone,
  listFilter,
  onClearListFilter,
}) {
  const [newName, setNewName] = useState('');
  const [newTeamName, setNewTeamName] = useState('');
  const [newSkillName, setNewSkillName] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [teamFilter, setTeamFilter] = useState('all');
  const [skillsSectionOpen, setSkillsSectionOpen] = useState(true);

  useEffect(() => {
    if (!listFilter) return;
    if (listFilter.type === 'team') setTeamFilter(listFilter.value);
    if (listFilter.type === 'employee') setSearchTerm(listFilter.label ?? '');
    if (listFilter.type === 'skill') setSearchTerm(listFilter.value ?? '');
  }, [listFilter]);

  const getProjectsForEmployee = (employeeId) => {
    const assignedIds = assignments
      .filter((a) => a.employeeId === employeeId)
      .map((a) => a.projectId);
    return projects.filter((p) => assignedIds.includes(p.id));
  };

  const handleAdd = () => {
    if (newName.trim()) {
      onAddEmployee(newName.trim());
      setNewName('');
    }
  };

  const handleAddTeam = () => {
    if (newTeamName.trim()) {
      onAddTeam(newTeamName.trim());
      setNewTeamName('');
    }
  };

  const handleAddSkill = () => {
    if (newSkillName.trim()) {
      onAddSkill(newSkillName.trim());
      setNewSkillName('');
    }
  };

  const passesListFilter = (emp) => {
    if (!listFilter) return true;
    const meta = getEmployeeMeta(emp.id);
    const tid = emp.effectiveTeamId;

    switch (listFilter.type) {
      case 'team':
        return (tid ?? '__none__') === listFilter.value;
      case 'skill':
        return (meta.skills ?? []).includes(listFilter.value);
      case 'project':
        return assignments.some(
          (a) => a.employeeId === emp.id && a.projectId === listFilter.value
        );
      case 'experience':
        return employeeInExperienceBucket(getEmployeeExperienceMonths(meta), listFilter.value);
      case 'workload': {
        const hasProjects = assignments.some((a) => a.employeeId === emp.id);
        return listFilter.value === 'with' ? hasProjects : !hasProjects;
      }
      case 'employee':
        return emp.id === listFilter.value;
      default:
        return true;
    }
  };

  const filteredEmployees = employees.filter((emp) => {
    const meta = getEmployeeMeta(emp.id);
    const q = searchTerm.trim().toLowerCase();
    const byName = emp.name.toLowerCase().includes(q);
    const bySkill = (meta.skills ?? []).some((s) => s.toLowerCase().includes(q));
    const bySearch = q ? (byName || bySkill) : true;
    const tid = emp.effectiveTeamId;
    const byTeam =
      teamFilter === 'all' ? true : (tid ?? '__none__') === teamFilter;
    return bySearch && byTeam && passesListFilter(emp);
  });

  const employeeGroups = useMemo(() => {
    const sorted = [...filteredEmployees].sort(sortByName);

    if (teamFilter !== 'all') {
      const teamName = teamFilter === '__none__'
        ? 'Без команды'
        : teams.find((t) => t.id === teamFilter)?.name ?? 'Команда';
      return sorted.length
        ? [{ teamId: teamFilter, teamName, employees: sorted }]
        : [];
    }

    const groups = [];
    for (const team of teams) {
      const groupEmployees = sorted.filter(
        (e) => e.effectiveTeamId === team.id
      );
      if (groupEmployees.length > 0) {
        groups.push({ teamId: team.id, teamName: team.name, employees: groupEmployees });
      }
    }
    const unassigned = sorted.filter((e) => !e.effectiveTeamId);
    if (unassigned.length > 0) {
      groups.push({ teamId: '__none__', teamName: 'Без команды', employees: unassigned });
    }
    return groups;
  }, [filteredEmployees, teams, teamFilter]);

  const renderEmployeeCard = (employee) => {
    const meta = getEmployeeMeta(employee.id);
    const teamId = employee.effectiveTeamId;
    return (
      <EmployeeCard
        key={employee.id}
        employee={employee}
        teamId={teamId}
        assignedProjects={getProjectsForEmployee(employee.id)}
        teams={teams}
        onRemoveAssignment={onRemoveAssignment}
        onSetEmployeeTeam={onSetEmployeeTeam}
        onRemoveEmployee={onRemoveEmployee}
        skillsCatalog={skillsCatalog}
        employeeSkills={meta.skills ?? []}
        startDate={meta.startDate ?? null}
        photo={meta.photo ?? null}
        socialLink={meta.socialLink ?? ''}
        phone={meta.phone ?? ''}
        onSetStartDate={onSetStartDate}
        onSetPhoto={onSetPhoto}
        onSetSocialLink={onSetSocialLink}
        onSetPhone={onSetPhone}
        onToggleSkill={onToggleSkill}
      />
    );
  };

  return (
    <div className="employees-panel">
      <h3>Сотрудники</h3>

      {listFilter && (
        <div className="active-filter-banner">
          <span>Фильтр: <strong>{listFilter.label}</strong></span>
          <button
            type="button"
            onClick={() => {
              setTeamFilter('all');
              setSearchTerm('');
              onClearListFilter?.();
            }}
          >
            ✕ Сбросить
          </button>
        </div>
      )}

      <div className="add-form">
        <input
          type="text"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
          placeholder="Имя нового сотрудника"
        />
        <button type="button" onClick={handleAdd}>Добавить</button>
      </div>
      <div className="add-form">
        <input
          type="text"
          value={newTeamName}
          onChange={(e) => setNewTeamName(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleAddTeam()}
          placeholder="Название новой команды"
        />
        <button type="button" onClick={handleAddTeam}>Создать команду</button>
      </div>

      <div className="skills-catalog-section">
        <button
          type="button"
          className="skills-catalog-toggle"
          onClick={() => setSkillsSectionOpen((v) => !v)}
        >
          Каталог скиллов ({skillsCatalog.length}) {skillsSectionOpen ? '▲' : '▼'}
        </button>
        {skillsSectionOpen && (
          <>
            <div className="add-form">
              <input
                type="text"
                value={newSkillName}
                onChange={(e) => setNewSkillName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAddSkill()}
                placeholder="Новый скилл (React, Python...)"
              />
              <button type="button" onClick={handleAddSkill}>Добавить скилл</button>
            </div>
            <div className="skills-catalog-list">
              {skillsCatalog.map((skill) => (
                <span key={skill} className="catalog-skill-chip">
                  {skill}
                  <button
                    type="button"
                    className="catalog-skill-remove"
                    onClick={() => onRemoveSkill(skill)}
                    title={`Удалить ${skill}`}
                  >
                    ×
                  </button>
                </span>
              ))}
              {skillsCatalog.length === 0 && (
                <span className="catalog-empty">Каталог пуст — добавьте скиллы</span>
              )}
            </div>
          </>
        )}
      </div>

      <div className="search-form">
        <input
          type="text"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="🔍 Поиск по имени или скиллу..."
        />
      </div>
      <div className="filter-form">
        <label>
          Команда:
          <select
            value={teamFilter}
            onChange={(e) => {
              setTeamFilter(e.target.value);
              onClearListFilter?.();
            }}
          >
            <option value="all">Все</option>
            {teams.map((t) => (
              <option key={t.id} value={t.id}>
                {t.name}
              </option>
            ))}
            <option value="__none__">Без команды</option>
          </select>
        </label>
      </div>

      <p className="filter-result-count">
        Показано: {filteredEmployees.length} из {employees.length}
      </p>

      <div className="employees-list">
        {employeeGroups.map((group) => (
          <section key={group.teamId} className="team-group">
            <div
              className="team-group-header"
              style={{ '--team-color': getTeamColor(group.teamId, teams) }}
            >
              <span className="team-group-dot" />
              <h4 className="team-group-title">{group.teamName}</h4>
              <span className="team-group-count">{group.employees.length}</span>
            </div>
            <div className="team-group-cards">
              {group.employees.map(renderEmployeeCard)}
            </div>
          </section>
        ))}
        {employeeGroups.length === 0 && (
          <p className="employees-empty">Сотрудники не найдены</p>
        )}
      </div>
    </div>
  );
}
