import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, onSnapshot, addDoc, deleteDoc, doc, query, orderBy, where, getDocs, updateDoc } from 'firebase/firestore';
import { saveTeamBackup } from './useTeamBackup';

export function useFirebaseEmployees() {
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, 'employees'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map((docSnap) => ({
        id: docSnap.id,
        ...docSnap.data(),
      }));
      setEmployees(data);
      setLoading(false);
    }, (error) => {
      console.error('Ошибка загрузки сотрудников:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const addEmployee = async (name) => {
    try {
      await addDoc(collection(db, 'employees'), {
        name,
        teamId: null,
        teamName: null,
        skills: [],
        startDate: null,
        photo: null,
        socialLink: '',
        phone: '',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error('Ошибка добавления сотрудника:', error);
    }
  };

  const setEmployeeTeam = async (employeeId, teamId, teamName, employeeName) => {
    try {
      await updateDoc(doc(db, 'employees', employeeId), {
        teamId: teamId ?? null,
        teamName: teamName ?? null,
        updatedAt: new Date().toISOString(),
      });
      saveTeamBackup(employeeId, teamId ?? null, teamName ?? null, employeeName ?? '');
    } catch (error) {
      console.error('Ошибка обновления команды сотрудника:', error);
    }
  };

  const updateEmployeeProfile = async (employeeId, patch) => {
    try {
      await updateDoc(doc(db, 'employees', employeeId), {
        ...patch,
        updatedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error('Ошибка обновления профиля сотрудника:', error);
    }
  };

  const removeEmployee = async (id) => {
    try {
      await deleteDoc(doc(db, 'employees', id));

      const q = query(collection(db, 'assignments'), where('employeeId', '==', id));
      const snapshot = await getDocs(q);
      const deletePromises = snapshot.docs.map((docSnapshot) =>
        deleteDoc(doc(db, 'assignments', docSnapshot.id))
      );
      await Promise.all(deletePromises);
    } catch (error) {
      console.error('Ошибка удаления сотрудника:', error);
    }
  };

  return {
    employees,
    addEmployee,
    setEmployeeTeam,
    updateEmployeeProfile,
    removeEmployee,
    loading,
  };
}
