import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { ProjectCard } from './ProjectCard';
import './ProjectsPool.css';

const PAGE_SIZES = [2, 3, 4, 6];

export function ProjectsPool({ projects, onAddProject, onRemoveProject }) {
  const [newTitle, setNewTitle] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(3);
  const [viewMode, setViewMode] = useState('carousel');

  const filteredProjects = useMemo(
    () => projects.filter((proj) =>
      proj.title.toLowerCase().includes(searchTerm.toLowerCase())
    ),
    [projects, searchTerm]
  );

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / pageSize));

  useEffect(() => {
    setPage((p) => Math.min(p, totalPages - 1));
  }, [totalPages, searchTerm, pageSize]);

  const pageProjects = useMemo(() => {
    const start = page * pageSize;
    return filteredProjects.slice(start, start + pageSize);
  }, [filteredProjects, page, pageSize]);

  const goPrev = useCallback(() => setPage((p) => Math.max(0, p - 1)), []);
  const goNext = useCallback(() => setPage((p) => Math.min(totalPages - 1, p + 1)), [totalPages]);
  const goToPage = useCallback((i) => setPage(i), []);

  const handleAdd = () => {
    if (newTitle.trim()) {
      onAddProject(newTitle.trim());
      setNewTitle('');
      setPage(0);
    }
  };

  const handleKeyDown = (e) => {
    if (viewMode !== 'carousel') return;
    if (e.key === 'ArrowLeft') goPrev();
    if (e.key === 'ArrowRight') goNext();
  };

  return (
    <div className="projects-pool" onKeyDown={handleKeyDown} tabIndex={0}>
      <div className="projects-pool-header">
        <h3>Все проекты</h3>
        <div className="view-toggle">
          <button
            type="button"
            className={viewMode === 'carousel' ? 'active' : ''}
            onClick={() => setViewMode('carousel')}
            title="Карусель"
          >
            ⊞
          </button>
          <button
            type="button"
            className={viewMode === 'list' ? 'active' : ''}
            onClick={() => setViewMode('list')}
            title="Список"
          >
            ☰
          </button>
        </div>
      </div>

      <div className="add-form">
        <input
          type="text"
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
          placeholder="Название нового проекта"
        />
        <button type="button" onClick={handleAdd}>Добавить</button>
      </div>

      <div className="search-form">
        <input
          type="text"
          value={searchTerm}
          onChange={(e) => { setSearchTerm(e.target.value); setPage(0); }}
          placeholder="🔍 Поиск проектов..."
        />
      </div>

      {viewMode === 'carousel' && (
        <div className="carousel-controls">
          <div className="carousel-nav">
            <button type="button" onClick={goPrev} disabled={page === 0} aria-label="Предыдущая страница">
              ‹
            </button>
            <span className="carousel-info">
              {filteredProjects.length === 0
                ? '0 проектов'
                : `${page + 1} / ${totalPages} · ${filteredProjects.length} проектов`}
            </span>
            <button type="button" onClick={goNext} disabled={page >= totalPages - 1} aria-label="Следующая страница">
              ›
            </button>
          </div>
          <label className="page-size-label">
            На странице:
            <select value={pageSize} onChange={(e) => { setPageSize(Number(e.target.value)); setPage(0); }}>
              {PAGE_SIZES.map((n) => (
                <option key={n} value={n}>{n}</option>
              ))}
            </select>
          </label>
        </div>
      )}

      {viewMode === 'carousel' ? (
        <>
          <div className="projects-carousel">
            {pageProjects.length > 0 ? (
              pageProjects.map((project) => (
                <ProjectCard
                  key={project.id}
                  project={project}
                  onRemove={onRemoveProject}
                />
              ))
            ) : (
              <div className="carousel-empty">Проекты не найдены</div>
            )}
          </div>
          {totalPages > 1 && (
            <div className="carousel-dots">
              {Array.from({ length: totalPages }, (_, i) => (
                <button
                  key={i}
                  type="button"
                  className={`carousel-dot ${i === page ? 'active' : ''}`}
                  onClick={() => goToPage(i)}
                  aria-label={`Страница ${i + 1}`}
                />
              ))}
            </div>
          )}
          <p className="carousel-hint">← → для перелистывания</p>
        </>
      ) : (
        <div className="projects-list">
          {filteredProjects.map((project) => (
            <ProjectCard
              key={project.id}
              project={project}
              onRemove={onRemoveProject}
            />
          ))}
        </div>
      )}
    </div>
  );
}
