import React, { useState, useRef } from 'react';
import { useDroppable } from '@dnd-kit/core';
import { ProjectChip } from './ProjectChip';
import {
  getTeamColor,
  formatExperienceMonths,
  getExperienceMonthsFromStartDate,
} from '../../utils/teamUtils';
import { compressImageFile } from '../../utils/imageUtils';
import './EmployeeCard.css';

export function EmployeeCard({
  employee,
  teamId,
  assignedProjects,
  teams,
  onRemoveAssignment,
  onSetEmployeeTeam,
  onRemoveEmployee,
  skillsCatalog,
  employeeSkills,
  startDate,
  photo,
  socialLink,
  phone,
  onSetStartDate,
  onSetPhoto,
  onSetSocialLink,
  onSetPhone,
  onToggleSkill,
}) {
  const [skillsOpen, setSkillsOpen] = useState(false);
  const [contactsOpen, setContactsOpen] = useState(false);
  const fileInputRef = useRef(null);
  const teamColor = getTeamColor(teamId, teams);
  const experienceMonths = getExperienceMonthsFromStartDate(startDate);

  const { setNodeRef, isOver } = useDroppable({
    id: employee.id,
    data: { employeeId: employee.id },
  });

  const handleRemoveEmployee = () => {
    if (window.confirm(`Удалить сотрудника ${employee.name}? Все его назначения также будут удалены.`)) {
      onRemoveEmployee(employee.id);
    }
  };

  const handlePhotoChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      alert('Выберите файл изображения');
      return;
    }
    try {
      const dataUrl = await compressImageFile(file);
      onSetPhoto(employee.id, dataUrl);
    } catch {
      alert('Не удалось загрузить фото');
    }
    e.target.value = '';
  };

  const socialHref = socialLink && !/^https?:\/\//i.test(socialLink)
    ? `https://${socialLink}`
    : socialLink;

  return (
    <div
      ref={setNodeRef}
      className={`employee-card ${isOver ? 'drag-over' : ''}`}
      style={{ '--team-color': teamColor }}
    >
      <div className="employee-card-top">
        <div className="employee-avatar-block">
          <button
            type="button"
            className={`employee-avatar-btn ${photo ? 'has-photo' : 'no-photo'}`}
            onClick={() => fileInputRef.current?.click()}
            title={photo ? 'Изменить фото' : 'Загрузить фото'}
          >
            {photo ? (
              <img src={photo} alt={employee.name} className="employee-avatar-img" />
            ) : (
              <>
                <span className="employee-avatar-placeholder">
                  {employee.name.charAt(0).toUpperCase()}
                </span>
                <span className="employee-avatar-camera" aria-hidden="true">📷</span>
              </>
            )}
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="employee-photo-input"
            onChange={handlePhotoChange}
          />
          {photo && (
            <button
              type="button"
              className="employee-photo-remove"
              onClick={() => onSetPhoto(employee.id, null)}
              title="Удалить фото"
            >
              ×
            </button>
          )}
          <span className="employee-photo-hint">
            {photo ? 'Нажмите, чтобы изменить фото' : 'Нажмите, чтобы загрузить фото'}
          </span>
        </div>
        <div className="employee-card-main">
          <div className="employee-card-header">
            <h4>{employee.name}</h4>
            <button onClick={handleRemoveEmployee} className="remove-employee-btn" title="Удалить сотрудника">✕</button>
          </div>
          <div className="employee-meta">
            <select
              className="team-select"
              value={teamId ?? '__none__'}
              onChange={(e) => onSetEmployeeTeam(employee.id, e.target.value === '__none__' ? null : e.target.value)}
              title="Команда"
              style={{ borderColor: teamColor, color: teamId ? teamColor : '#666' }}
            >
              <option value="__none__">Без команды</option>
              {teams.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      <div className="employee-experience">
        <label>
          Дата начала работы:
          <input
            type="date"
            value={startDate ?? ''}
            max={new Date().toISOString().slice(0, 10)}
            onChange={(e) => onSetStartDate(employee.id, e.target.value)}
          />
        </label>
        <span className="experience-hint">
          {startDate ? `Стаж: ${formatExperienceMonths(experienceMonths)}` : 'Укажите дату — стаж посчитается автоматически'}
        </span>
      </div>

      <div className="employee-contacts-section">
        <button
          type="button"
          className="contacts-toggle"
          onClick={() => setContactsOpen((v) => !v)}
        >
          Контакты {contactsOpen ? '▲' : '▼'}
        </button>
        {contactsOpen && (
          <div className="contacts-fields">
            <label>
              Телефон:
              <input
                type="tel"
                value={phone}
                onChange={(e) => onSetPhone(employee.id, e.target.value)}
                placeholder="+7 (999) 000-00-00"
              />
            </label>
            <label>
              Соц. сеть:
              <input
                type="url"
                value={socialLink}
                onChange={(e) => onSetSocialLink(employee.id, e.target.value)}
                placeholder="t.me/username или vk.com/..."
              />
            </label>
            {socialLink && (
              <a
                href={socialHref}
                target="_blank"
                rel="noopener noreferrer"
                className="social-link-preview"
              >
                Открыть профиль ↗
              </a>
            )}
          </div>
        )}
        {!contactsOpen && phone && (
          <span className="contacts-preview">📞 {phone}</span>
        )}
      </div>

      <div className="employee-skills-section">
        <button
          type="button"
          className="skills-toggle"
          onClick={() => setSkillsOpen((v) => !v)}
        >
          Скиллы ({employeeSkills.length}) {skillsOpen ? '▲' : '▼'}
        </button>
        {employeeSkills.length > 0 && (
          <div className="skills-tags">
            {employeeSkills.map((skill) => (
              <span key={skill} className="skill-tag">{skill}</span>
            ))}
          </div>
        )}
        {skillsOpen && (
          <div className="skills-picker">
            {skillsCatalog.map((skill) => {
              const active = employeeSkills.includes(skill);
              return (
                <button
                  key={skill}
                  type="button"
                  className={`skill-option ${active ? 'active' : ''}`}
                  onClick={() => onToggleSkill(employee.id, skill)}
                >
                  {skill}
                </button>
              );
            })}
            {skillsCatalog.length === 0 && (
              <span className="skills-empty-hint">Добавьте скиллы в каталог выше</span>
            )}
          </div>
        )}
      </div>

      <div className="projects-list">
        {assignedProjects.map((project) => (
          <ProjectChip
            key={project.id}
            project={project}
            employeeId={employee.id}
            onRemove={onRemoveAssignment}
          />
        ))}
        {assignedProjects.length === 0 && (
          <span className="empty-projects">Нет проектов</span>
        )}
      </div>
    </div>
  );
}
