import { useState, useEffect, useCallback } from 'react';
import { doc, onSnapshot, getDoc, setDoc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';

const SETTINGS_REF = doc(db, 'settings', 'app');

const DEFAULT_CATALOG = ['JavaScript', 'React', 'Python', 'SQL', 'DevOps'];

async function ensureSettingsDoc() {
  const snap = await getDoc(SETTINGS_REF);
  if (!snap.exists()) {
    await setDoc(SETTINGS_REF, {
      skillsCatalog: DEFAULT_CATALOG,
      updatedAt: new Date().toISOString(),
    });
  }
}

export function useFirebaseAppSettings() {
  const [skillsCatalog, setSkillsCatalog] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    ensureSettingsDoc().catch(console.error);

    const unsubscribe = onSnapshot(
      SETTINGS_REF,
      (snapshot) => {
        const data = snapshot.data();
        setSkillsCatalog(
          Array.isArray(data?.skillsCatalog) ? data.skillsCatalog : DEFAULT_CATALOG
        );
        setLoading(false);
      },
      (error) => {
        console.error('Ошибка загрузки настроек:', error);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, []);

  const addSkillToCatalog = useCallback(async (name) => {
    const trimmed = name.trim();
    if (!trimmed) return;
    try {
      await ensureSettingsDoc();
      const snap = await getDoc(SETTINGS_REF);
      const current = snap.data()?.skillsCatalog ?? [];
      if (current.some((s) => s.toLowerCase() === trimmed.toLowerCase())) return;
      await updateDoc(SETTINGS_REF, {
        skillsCatalog: [...current, trimmed].sort((a, b) => a.localeCompare(b, 'ru')),
        updatedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error('Ошибка добавления скилла:', error);
    }
  }, []);

  const removeSkillFromCatalog = useCallback(async (name) => {
    try {
      const snap = await getDoc(SETTINGS_REF);
      const current = snap.data()?.skillsCatalog ?? [];
      await updateDoc(SETTINGS_REF, {
        skillsCatalog: current.filter((s) => s !== name),
        updatedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error('Ошибка удаления скилла:', error);
    }
  }, []);

  const mergeSkillsCatalog = useCallback(async (names) => {
    if (!names?.length) return;
    try {
      await ensureSettingsDoc();
      const snap = await getDoc(SETTINGS_REF);
      const current = snap.data()?.skillsCatalog ?? [];
      const merged = [...new Set([...current, ...names])].sort((a, b) =>
        a.localeCompare(b, 'ru')
      );
      await updateDoc(SETTINGS_REF, {
        skillsCatalog: merged,
        updatedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error('Ошибка слияния каталога скиллов:', error);
    }
  }, []);

  return {
    skillsCatalog,
    addSkillToCatalog,
    removeSkillFromCatalog,
    mergeSkillsCatalog,
    loading,
  };
}
