import { useEffect, useRef } from 'react';
import { doc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { resolveEmployeeTeamId } from '../utils/teamUtils';

const STORAGE_KEY = 'cpito_team_backup_v1';

function loadBackup() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

export function saveTeamBackup(employeeId, teamId, teamName, employeeName) {
  const backup = loadBackup();
  backup[employeeId] = { teamId, teamName, employeeName };
  localStorage.setItem(STORAGE_KEY, JSON.stringify(backup));
}

export function useTeamRestore(employees, teams) {
  const syncedRef = useRef(new Set());

  useEffect(() => {
    if (!employees.length || !teams.length) return;

    const backup = loadBackup();
    const teamById = new Map(teams.map((t) => [t.id, t]));
    const teamByName = new Map(teams.map((t) => [t.name.trim().toLowerCase(), t]));

    employees.forEach(async (employee) => {
      if (syncedRef.current.has(employee.id)) return;

      let resolved = resolveEmployeeTeamId(employee, teams);

      if (!resolved) {
        const saved = backup[employee.id];
        if (saved) {
          if (saved.teamId && teamById.has(saved.teamId)) {
            resolved = saved.teamId;
          } else if (saved.teamName) {
            resolved = teamByName.get(saved.teamName.trim().toLowerCase())?.id ?? null;
          }
        }
      }

      const team = resolved ? teamById.get(resolved) : null;
      const correctTeamName = team?.name ?? null;
      const needsUpdate =
        (resolved && employee.teamId !== resolved) ||
        (resolved && employee.teamName !== correctTeamName) ||
        (!resolved && employee.teamId) ||
        (!resolved && employee.teamName);

      if (resolved) {
        saveTeamBackup(employee.id, resolved, correctTeamName, employee.name);
      }

      if (needsUpdate) {
        syncedRef.current.add(employee.id);
        try {
          await updateDoc(doc(db, 'employees', employee.id), {
            teamId: resolved,
            teamName: correctTeamName,
            updatedAt: new Date().toISOString(),
          });
        } catch (e) {
          console.error('Ошибка синхронизации команды:', e);
          syncedRef.current.delete(employee.id);
        }
      }
    });
  }, [employees, teams]);
}
