import React, { useMemo, useCallback } from 'react';
import {
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { TeamStats } from '../TeamStats';
import {
  TEAM_COLORS,
  UNASSIGNED_COLOR,
  getTeamColor,
  formatAverageExperience,
  experienceBucket,
  getEmployeeExperienceMonths,
  countEmployeesByTeam,
} from '../../utils/teamUtils';
import './StatsDashboard.css';

function ChartBlock({ title, hint, children }) {
  return (
    <div className="chart-block">
      <h4>{title}</h4>
      {hint && <p className="chart-hint">{hint}</p>}
      {children}
    </div>
  );
}

function CustomTooltip({ active, payload, labelFormatter }) {
  if (!active || !payload?.length) return null;
  const item = payload[0];
  const label = labelFormatter ? labelFormatter(item.payload) : item.name;
  return (
    <div className="chart-tooltip">
      <strong>{label}</strong>
      <span>{item.value} чел.</span>
    </div>
  );
}

export function StatsDashboard({
  teams,
  employees,
  projects,
  assignments,
  skillsCatalog,
  employeeMeta,
  onNavigateToEmployees,
}) {
  const teamChartData = useMemo(() => {
    const { counts, unassigned } = countEmployeesByTeam(employees, teams);
    const data = teams
      .map((t) => ({ id: t.id, name: t.name, count: counts.get(t.id) ?? 0 }))
      .filter((d) => d.count > 0);
    if (unassigned > 0) data.push({ id: '__none__', name: 'Без команды', count: unassigned });
    return data.sort((a, b) => b.count - a.count);
  }, [teams, employees]);

  const projectTasksData = useMemo(() => {
    const counts = new Map(projects.map((p) => [p.id, { id: p.id, name: p.title, tasks: 0 }]));
    for (const a of assignments) {
      if (counts.has(a.projectId)) counts.get(a.projectId).tasks += 1;
    }
    return [...counts.values()]
      .sort((a, b) => b.tasks - a.tasks)
      .slice(0, 12);
  }, [projects, assignments]);

  const skillsData = useMemo(() => {
    const counts = new Map(skillsCatalog.map((s) => [s, 0]));
    for (const meta of Object.values(employeeMeta)) {
      for (const skill of meta.skills ?? []) {
        if (counts.has(skill)) counts.set(skill, counts.get(skill) + 1);
      }
    }
    return [...counts.entries()]
      .map(([name, count]) => ({ name, count }))
      .filter((d) => d.count > 0)
      .sort((a, b) => b.count - a.count);
  }, [skillsCatalog, employeeMeta]);

  const experienceData = useMemo(() => {
    const buckets = ['0–1 год', '2–3 года', '4–5 лет', '6–10 лет', '10+ лет'];
    const counts = Object.fromEntries(buckets.map((b) => [b, 0]));
    for (const e of employees) {
      const months = getEmployeeExperienceMonths(employeeMeta[e.id]);
      counts[experienceBucket(months)] += 1;
    }
    return buckets.map((name) => ({ name, count: counts[name] }));
  }, [employees, employeeMeta]);

  const employeeLoadData = useMemo(() => {
    const counts = new Map(employees.map((e) => [e.id, { id: e.id, name: e.name, projects: 0 }]));
    for (const a of assignments) {
      if (counts.has(a.employeeId)) counts.get(a.employeeId).projects += 1;
    }
    return [...counts.values()]
      .sort((a, b) => b.projects - a.projects)
      .slice(0, 10);
  }, [employees, assignments]);

  const workloadPie = useMemo(() => {
    let withProjects = 0;
    let without = 0;
    const byEmp = new Map();
    for (const a of assignments) byEmp.set(a.employeeId, (byEmp.get(a.employeeId) ?? 0) + 1);
    for (const e of employees) {
      if ((byEmp.get(e.id) ?? 0) > 0) withProjects += 1;
      else without += 1;
    }
    return [
      { id: 'with', name: 'С проектами', value: withProjects },
      { id: 'without', name: 'Без проектов', value: without },
    ].filter((d) => d.value > 0);
  }, [employees, assignments]);

  const avgExperience = useMemo(() => {
    if (employees.length === 0) return '—';
    const sum = employees.reduce(
      (acc, e) => acc + getEmployeeExperienceMonths(employeeMeta[e.id]),
      0
    );
    return formatAverageExperience(sum, employees.length);
  }, [employees, employeeMeta]);

  const getTeamColorForChart = useCallback(
    (entry) => (entry.id === '__none__' ? UNASSIGNED_COLOR : getTeamColor(entry.id, teams)),
    [teams]
  );

  const handleTeamPieClick = (_, index) => {
    const item = teamChartData[index];
    if (item) onNavigateToEmployees?.({ type: 'team', value: item.id, label: item.name });
  };

  const handleTeamCardClick = (teamId) => {
    const name = teamId === '__none__'
      ? 'Без команды'
      : teams.find((t) => t.id === teamId)?.name ?? '';
    onNavigateToEmployees?.({ type: 'team', value: teamId, label: name });
  };

  const renderTeamPie = () => (
    <ResponsiveContainer width="100%" height={280}>
      <PieChart>
        <Pie
          data={teamChartData}
          dataKey="count"
          nameKey="name"
          cx="50%"
          cy="45%"
          outerRadius={85}
          innerRadius={40}
          paddingAngle={2}
          onClick={handleTeamPieClick}
          style={{ cursor: 'pointer' }}
        >
          {teamChartData.map((entry, i) => (
            <Cell key={entry.id} fill={getTeamColorForChart(entry)} />
          ))}
        </Pie>
        <Tooltip
          formatter={(value, _name, props) => [`${value} чел.`, props.payload.name]}
        />
      </PieChart>
    </ResponsiveContainer>
  );

  const renderTeamLegend = () => (
    <div className="chart-legend">
      {teamChartData.map((entry) => (
        <button
          type="button"
          key={entry.id}
          className="legend-item"
          onClick={() => handleTeamCardClick(entry.id)}
        >
          <span className="legend-dot" style={{ background: getTeamColorForChart(entry) }} />
          <span className="legend-label">{entry.name}</span>
          <span className="legend-value">{entry.count}</span>
        </button>
      ))}
    </div>
  );

  return (
    <div className="stats-dashboard">
      <TeamStats
        teams={teams}
        employees={employees}
        onTeamClick={handleTeamCardClick}
      />

      <div className="stats-summary-cards">
        <div className="summary-card">
          <span className="summary-value">{employees.length}</span>
          <span className="summary-label">Сотрудников</span>
        </div>
        <div className="summary-card">
          <span className="summary-value">{projects.length}</span>
          <span className="summary-label">Проектов</span>
        </div>
        <div className="summary-card">
          <span className="summary-value">{avgExperience}</span>
          <span className="summary-label">Средний стаж</span>
        </div>
      </div>

      <ChartBlock title="Распределение по командам" hint="Нажмите на сектор или легенду — откроется список сотрудников">
        {teamChartData.length > 0 ? (
          <>
            {renderTeamPie()}
            {renderTeamLegend()}
          </>
        ) : (
          <p className="chart-empty">Нет данных</p>
        )}
      </ChartBlock>

      <ChartBlock
        title="Сотрудники по проектам"
        hint="Сколько человек работает над каждым проектом. Нажмите на столбец."
      >
        {projectTasksData.length > 0 ? (
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={projectTasksData} margin={{ top: 5, right: 5, left: -10, bottom: 50 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
              <XAxis dataKey="name" tick={{ fontSize: 10 }} angle={-35} textAnchor="end" interval={0} height={55} />
              <YAxis allowDecimals={false} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${v} чел.`, 'На проекте']} />
              <Bar
                dataKey="tasks"
                fill="#667eea"
                radius={[4, 4, 0, 0]}
                name="Сотрудников"
                cursor="pointer"
                onClick={(raw) => {
                  const data = raw?.payload ?? raw;
                  if (data?.id) {
                    onNavigateToEmployees?.({
                      type: 'project',
                      value: data.id,
                      label: data.name,
                    });
                  }
                }}
              />
            </BarChart>
          </ResponsiveContainer>
        ) : (
          <p className="chart-empty">Нет проектов или привязок</p>
        )}
      </ChartBlock>

      <ChartBlock title="Стаж сотрудников" hint="Нажмите на столбец — фильтр по группе стажа">
        {employees.length > 0 ? (
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={experienceData} margin={{ top: 5, right: 5, left: -10, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} />
              <YAxis allowDecimals={false} tick={{ fontSize: 11 }} />
              <Tooltip content={<CustomTooltip labelFormatter={(p) => p.name} />} />
              <Bar
                dataKey="count"
                fill="#43e97b"
                radius={[4, 4, 0, 0]}
                cursor="pointer"
                onClick={(raw) => {
                  const data = raw?.payload ?? raw;
                  if (data?.name) {
                    onNavigateToEmployees?.({ type: 'experience', value: data.name, label: data.name });
                  }
                }}
              />
            </BarChart>
          </ResponsiveContainer>
        ) : (
          <p className="chart-empty">Нет сотрудников</p>
        )}
      </ChartBlock>

      <ChartBlock title="Занятость: с проектами / без" hint="Нажмите на сектор">
        {workloadPie.length > 0 ? (
          <>
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie
                  data={workloadPie}
                  dataKey="value"
                  nameKey="name"
                  cx="50%"
                  cy="50%"
                  outerRadius={75}
                  onClick={(_, index) => {
                    const item = workloadPie[index];
                    if (item) {
                      onNavigateToEmployees?.({
                        type: 'workload',
                        value: item.id,
                        label: item.name,
                      });
                    }
                  }}
                  style={{ cursor: 'pointer' }}
                >
                  {workloadPie.map((entry, i) => (
                    <Cell key={entry.id} fill={entry.id === 'with' ? '#4facfe' : '#b0bec5'} />
                  ))}
                </Pie>
                <Tooltip formatter={(v, _n, p) => [`${v} чел.`, p.payload.name]} />
              </PieChart>
            </ResponsiveContainer>
            <div className="chart-legend">
              {workloadPie.map((entry) => (
                <button
                  type="button"
                  key={entry.id}
                  className="legend-item"
                  onClick={() => onNavigateToEmployees?.({
                    type: 'workload',
                    value: entry.id,
                    label: entry.name,
                  })}
                >
                  <span className="legend-dot" style={{ background: entry.id === 'with' ? '#4facfe' : '#b0bec5' }} />
                  <span className="legend-label">{entry.name}</span>
                  <span className="legend-value">{entry.value}</span>
                </button>
              ))}
            </div>
          </>
        ) : (
          <p className="chart-empty">Нет сотрудников</p>
        )}
      </ChartBlock>

      <ChartBlock title="Проектов на сотрудника (топ-10)" hint="Нажмите на столбец — откроется карточка сотрудника">
        {employeeLoadData.length > 0 ? (
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={employeeLoadData} margin={{ top: 10, right: 10, left: -10, bottom: 55 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
              <XAxis dataKey="name" tick={{ fontSize: 10 }} angle={-35} textAnchor="end" interval={0} height={60} />
              <YAxis allowDecimals={false} tick={{ fontSize: 11 }} width={30} />
              <Tooltip formatter={(v) => [`${v} проект(ов)`, 'Нагрузка']} />
              <Bar
                dataKey="projects"
                fill="#4facfe"
                radius={[4, 4, 0, 0]}
                cursor="pointer"
                onClick={(raw) => {
                  const data = raw?.payload ?? raw;
                  if (data?.id) {
                    onNavigateToEmployees?.({
                      type: 'employee',
                      value: data.id,
                      label: data.name,
                    });
                  }
                }}
              />
            </BarChart>
          </ResponsiveContainer>
        ) : (
          <p className="chart-empty">Нет сотрудников</p>
        )}
      </ChartBlock>

      {skillsData.length > 0 && (
        <ChartBlock title="Скиллы (круговая)" hint="Нажмите на сектор или легенду">
          <ResponsiveContainer width="100%" height={220}>
            <PieChart>
              <Pie
                data={skillsData.map((d) => ({ ...d, value: d.count }))}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                outerRadius={75}
                onClick={(_, index) => {
                  const item = skillsData[index];
                  if (item) {
                    onNavigateToEmployees?.({ type: 'skill', value: item.name, label: item.name });
                  }
                }}
                style={{ cursor: 'pointer' }}
              >
                {skillsData.map((_, i) => (
                  <Cell key={i} fill={TEAM_COLORS[i % TEAM_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip formatter={(v, _n, p) => [`${v} чел.`, p.payload.name]} />
            </PieChart>
          </ResponsiveContainer>
          <div className="chart-legend">
            {skillsData.map((entry, i) => (
              <button
                type="button"
                key={entry.name}
                className="legend-item"
                onClick={() => onNavigateToEmployees?.({ type: 'skill', value: entry.name, label: entry.name })}
              >
                <span className="legend-dot" style={{ background: TEAM_COLORS[i % TEAM_COLORS.length] }} />
                <span className="legend-label">{entry.name}</span>
                <span className="legend-value">{entry.count}</span>
              </button>
            ))}
          </div>
        </ChartBlock>
      )}
    </div>
  );
}
