export const TEAM_COLORS = [
  '#667eea', '#764ba2', '#43e97b', '#4facfe', '#fa709a',
  '#fee140', '#30cfd0', '#f093fb', '#a18cd1', '#ff8a65',
];

export const UNASSIGNED_COLOR = '#b0bec5';

export function getTeamColor(teamId, teams) {
  if (!teamId || teamId === '__none__') return UNASSIGNED_COLOR;
  const idx = teams.findIndex((t) => t.id === teamId);
  return idx >= 0 ? TEAM_COLORS[idx % TEAM_COLORS.length] : UNASSIGNED_COLOR;
}

function buildTeamLookups(teams) {
  const validIds = new Set(teams.map((t) => t.id));
  const byName = new Map(
    teams.map((t) => [t.name.trim().toLowerCase(), t.id])
  );
  return { validIds, byName };
}

export function resolveEmployeeTeamId(employee, teams) {
  if (!employee) return null;
  const { validIds, byName } = buildTeamLookups(teams);

  if (employee.teamId && validIds.has(employee.teamId)) {
    return employee.teamId;
  }

  // teamId иногда сохранён как название команды, а не id документа
  if (employee.teamId) {
    const fromIdAsName = byName.get(String(employee.teamId).trim().toLowerCase());
    if (fromIdAsName) return fromIdAsName;
  }

  const candidates = [employee.teamName, employee.team, employee.group].filter(Boolean);
  for (const raw of candidates) {
    const match = byName.get(String(raw).trim().toLowerCase());
    if (match) return match;
  }

  return null;
}

export function getEffectiveTeamId(employee, teams) {
  return employee?.effectiveTeamId ?? resolveEmployeeTeamId(employee, teams);
}

export function enrichEmployeesWithTeams(employees, teams) {
  return employees.map((e) => ({
    ...e,
    effectiveTeamId: resolveEmployeeTeamId(e, teams),
  }));
}

export function countEmployeesByTeam(employees, teams) {
  const counts = new Map(teams.map((t) => [t.id, 0]));
  let unassigned = 0;

  for (const e of employees) {
    const tid = getEffectiveTeamId(e, teams);
    if (tid && counts.has(tid)) {
      counts.set(tid, (counts.get(tid) ?? 0) + 1);
    } else {
      unassigned += 1;
    }
  }

  return { counts, unassigned };
}

export function getExperienceMonthsFromStartDate(startDate) {
  if (!startDate) return 0;
  const start = new Date(`${startDate}T00:00:00`);
  if (Number.isNaN(start.getTime())) return 0;
  const now = new Date();
  let months = (now.getFullYear() - start.getFullYear()) * 12 + (now.getMonth() - start.getMonth());
  if (now.getDate() < start.getDate()) months -= 1;
  return Math.max(0, months);
}

export function getEmployeeExperienceMonths(meta) {
  if (!meta) return 0;
  if (meta.startDate) return getExperienceMonthsFromStartDate(meta.startDate);
  return meta.experienceMonths ?? 0;
}

export function formatExperienceMonths(totalMonths) {
  if (totalMonths <= 0) return '0 мес.';
  if (totalMonths < 12) return `${Math.round(totalMonths)} мес.`;
  const years = Math.floor(totalMonths / 12);
  const months = Math.round(totalMonths % 12);
  if (months === 0) return `${years} ${years === 1 ? 'год' : years < 5 ? 'года' : 'лет'}`;
  return `${years} г. ${months} мес.`;
}

export function formatAverageExperience(totalMonths, count) {
  if (count === 0) return '—';
  const avg = totalMonths / count;
  if (avg < 12) return `${Math.max(1, Math.round(avg))} мес.`;
  return `${(avg / 12).toFixed(1)} лет`;
}

export function experienceBucket(months) {
  const years = months / 12;
  if (years <= 1) return '0–1 год';
  if (years <= 3) return '2–3 года';
  if (years <= 5) return '4–5 лет';
  if (years <= 10) return '6–10 лет';
  return '10+ лет';
}

export function employeeInExperienceBucket(months, bucket) {
  return experienceBucket(months) === bucket;
}
