import React, { useState, useMemo, useCallback } from 'react';
import { DndContext } from '@dnd-kit/core';
import { EmployeesPanel } from './components/EmployeesPanel';
import { ProjectsPool } from './components/ProjectsPool';
import { StatsDashboard } from './components/StatsDashboard';
import { useAssignments } from './hooks/useAssignments';
import { useFirebaseEmployees } from './hooks/useFirebaseEmployees';
import { useFirebaseProjects } from './hooks/useFirebaseProjects';
import { useFirebaseTeams } from './hooks/useFirebaseTeams';
import { useFirebaseAppSettings } from './hooks/useFirebaseAppSettings';
import { useCloudMigration } from './hooks/useCloudMigration';
import { useTeamRestore } from './hooks/useTeamBackup';
import { enrichEmployeesWithTeams } from './utils/teamUtils';
import { getEmployeeProfile, buildEmployeeMetaMap } from './utils/employeeUtils';
import './App.css';

function App() {
  const [activeTab, setActiveTab] = useState('work');
  const [listFilter, setListFilter] = useState(null);

  const {
    employees,
    addEmployee,
    setEmployeeTeam,
    updateEmployeeProfile,
    removeEmployee,
    loading: employeesLoading,
  } = useFirebaseEmployees();
  const { projects, addProject, removeProject, loading: projectsLoading } = useFirebaseProjects();
  const { assignments, removeAssignment, handleDragEnd, loading: assignmentsLoading } = useAssignments();
  const { teams, addTeam, loading: teamsLoading } = useFirebaseTeams();
  const {
    skillsCatalog,
    addSkillToCatalog,
    removeSkillFromCatalog,
    mergeSkillsCatalog,
    loading: settingsLoading,
  } = useFirebaseAppSettings();

  useCloudMigration(employees, updateEmployeeProfile, mergeSkillsCatalog);
  useTeamRestore(employees, teams);

  const enrichedEmployees = useMemo(
    () => enrichEmployeesWithTeams(employees, teams),
    [employees, teams]
  );

  const employeeMeta = useMemo(
    () => buildEmployeeMetaMap(enrichedEmployees),
    [enrichedEmployees]
  );

  const getEmployeeMeta = useCallback(
    (employeeId) => {
      const emp = enrichedEmployees.find((e) => e.id === employeeId);
      return getEmployeeProfile(emp);
    },
    [enrichedEmployees]
  );

  const handleSetEmployeeTeam = useCallback((employeeId, teamId) => {
    const employee = employees.find((e) => e.id === employeeId);
    const team = teams.find((t) => t.id === teamId);
    setEmployeeTeam(employeeId, teamId, team?.name ?? null, employee?.name ?? '');
  }, [employees, teams, setEmployeeTeam]);

  const setEmployeeStartDate = useCallback(
    (employeeId, startDate) => updateEmployeeProfile(employeeId, { startDate: startDate || null }),
    [updateEmployeeProfile]
  );

  const setEmployeePhoto = useCallback(
    (employeeId, photo) => updateEmployeeProfile(employeeId, { photo: photo || null }),
    [updateEmployeeProfile]
  );

  const setEmployeeSocialLink = useCallback(
    (employeeId, socialLink) => updateEmployeeProfile(employeeId, { socialLink: socialLink ?? '' }),
    [updateEmployeeProfile]
  );

  const setEmployeePhone = useCallback(
    (employeeId, phone) => updateEmployeeProfile(employeeId, { phone: phone ?? '' }),
    [updateEmployeeProfile]
  );

  const toggleEmployeeSkill = useCallback(
    (employeeId, skill) => {
      const emp = employees.find((e) => e.id === employeeId);
      const skills = emp?.skills ?? [];
      const has = skills.includes(skill);
      updateEmployeeProfile(employeeId, {
        skills: has ? skills.filter((s) => s !== skill) : [...skills, skill],
      });
    },
    [employees, updateEmployeeProfile]
  );

  const handleNavigateToEmployees = useCallback((filter) => {
    setListFilter(filter);
    setActiveTab('work');
  }, []);

  const handleClearListFilter = useCallback(() => setListFilter(null), []);

  if (employeesLoading || projectsLoading || assignmentsLoading || teamsLoading || settingsLoading) {
    return <div className="loading">Загрузка...</div>;
  }

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div className="app-wrapper">
        <div className="app-tabs">
          <button
            type="button"
            className={`app-tab ${activeTab === 'work' ? 'active' : ''}`}
            onClick={() => setActiveTab('work')}
          >
            Сотрудники и проекты
          </button>
          <button
            type="button"
            className={`app-tab ${activeTab === 'stats' ? 'active' : ''}`}
            onClick={() => setActiveTab('stats')}
          >
            Статистика
          </button>
        </div>

        <div className="app-container">
          {activeTab === 'work' && (
            <div className="tab-work">
              <EmployeesPanel
                employees={enrichedEmployees}
                assignments={assignments}
                projects={projects}
                teams={teams}
                onRemoveAssignment={removeAssignment}
                onAddEmployee={addEmployee}
                onAddTeam={addTeam}
                onSetEmployeeTeam={handleSetEmployeeTeam}
                onRemoveEmployee={removeEmployee}
                skillsCatalog={skillsCatalog}
                onAddSkill={addSkillToCatalog}
                onRemoveSkill={removeSkillFromCatalog}
                getEmployeeMeta={getEmployeeMeta}
                onToggleSkill={toggleEmployeeSkill}
                onSetStartDate={setEmployeeStartDate}
                onSetPhoto={setEmployeePhoto}
                onSetSocialLink={setEmployeeSocialLink}
                onSetPhone={setEmployeePhone}
                listFilter={listFilter}
                onClearListFilter={handleClearListFilter}
              />
              <ProjectsPool
                projects={projects}
                onAddProject={addProject}
                onRemoveProject={removeProject}
              />
            </div>
          )}

          {activeTab === 'stats' && (
            <div className="tab-stats">
              <StatsDashboard
                teams={teams}
                employees={enrichedEmployees}
                projects={projects}
                assignments={assignments}
                skillsCatalog={skillsCatalog}
                employeeMeta={employeeMeta}
                onNavigateToEmployees={handleNavigateToEmployees}
              />
            </div>
          )}
        </div>
      </div>
    </DndContext>
  );
}

export default App;
