import React, { useMemo } from 'react';
import { getTeamColor, UNASSIGNED_COLOR, countEmployeesByTeam } from '../../utils/teamUtils';
import './TeamStats.css';

export function TeamStats({ teams, employees, onTeamClick }) {
  const { rows, total } = useMemo(() => {
    const { counts, unassigned } = countEmployeesByTeam(employees, teams);

    const items = teams
      .map((t) => ({ id: t.id, name: t.name, count: counts.get(t.id) ?? 0 }))
      .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name, 'ru'));

    if (unassigned > 0) {
      items.push({ id: '__none__', name: 'Без команды', count: unassigned });
    }

    const sum = items.reduce((acc, r) => acc + r.count, 0);
    return { rows: items, total: sum };
  }, [teams, employees]);

  return (
    <div className="team-stats">
      <h3>Численность команд</h3>
      <div className="team-stats-grid">
        {rows.map((r) => {
          const color = r.id === '__none__' ? UNASSIGNED_COLOR : getTeamColor(r.id, teams);
          const pct = total > 0 ? Math.round((r.count / total) * 100) : 0;
          return (
            <button
              type="button"
              key={r.id}
              className="team-stats-card"
              style={{ '--team-color': color }}
              onClick={() => onTeamClick?.(r.id)}
              title={`Показать сотрудников: ${r.name}`}
            >
              <div className="team-stats-card-header">
                <span className="team-stats-dot" />
                <span className="team-stats-card-name">{r.name}</span>
              </div>
              <div className="team-stats-card-numbers">
                <span className="team-stats-card-count">{r.count}</span>
                <span className="team-stats-card-pct">{pct}%</span>
              </div>
              <div className="team-stats-card-bar">
                <div className="team-stats-card-fill" style={{ width: `${pct}%` }} />
              </div>
            </button>
          );
        })}
        <div className="team-stats-card team-stats-card-total">
          <div className="team-stats-card-header">
            <span className="team-stats-card-name">ИТОГО</span>
          </div>
          <div className="team-stats-card-numbers">
            <span className="team-stats-card-count">{total}</span>
            <span className="team-stats-card-pct">100%</span>
          </div>
        </div>
      </div>
    </div>
  );
}
