import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, onSnapshot, addDoc, deleteDoc, doc, query, orderBy, where, getDocs } from 'firebase/firestore';

export function useFirebaseProjects() {
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, 'projects'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setProjects(data);
      setLoading(false);
    }, (error) => {
      console.error("Ошибка загрузки проектов:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const addProject = async (title) => {
    try {
      await addDoc(collection(db, 'projects'), {
        title,
        createdAt: new Date().toISOString()
      });
    } catch (error) {
      console.error("Ошибка добавления проекта:", error);
    }
  };

  const removeProject = async (id) => {
    try {
      // 1. Удаляем проект
      await deleteDoc(doc(db, 'projects', id));

      // 2. Удаляем все назначения, где этот проект
      const q = query(collection(db, 'assignments'), where('projectId', '==', id));
      const snapshot = await getDocs(q);
      const deletePromises = snapshot.docs.map(docSnapshot => deleteDoc(doc(db, 'assignments', docSnapshot.id)));
      await Promise.all(deletePromises);
    } catch (error) {
      console.error("Ошибка удаления проекта:", error);
    }
  };

  return { projects, addProject, removeProject, loading };
}